/*
 * Curriculum data for the ALX / Holberton study planner.
 *
 * Every project has:
 *   id     unique key (progress is stored against it, so don't rename ids)
 *   title  display name
 *   repo   "owner/name" of a public student repo whose README lists the tasks
 *   path   folder inside that repo (omit for one-repo projects)
 *   days   number of ~2-hour study sessions to budget
 *   area   colour tag
 *   learn  what you should be able to explain afterwards
 *   res    [label, url] public learning resources
 *   plan   (optional) explicit per-session instructions; otherwise generated
 *
 * Project order inside a track = the order you study it in.
 */

const R = {
  ll: "micahondiwa/alx-low_level_programming",
  hl: "ngugimuchangi/alx-higher_level_programming",
  se: "micahondiwa/alx-system_engineering-devops",
  bp: "micahondiwa/alx-backend-python",
  bj: "micahondiwa/alx-backend-javascript",
  bs: "micahondiwa/alx-backend-storage",
  bu: "micahondiwa/alx-backend-user-data",
  bb: "micahondiwa/alx-backend",
  bi: "micahondiwa/alx-interview",
  fe: "bagoviggo/alx-frontend",
  re: "bagoviggo/alx-react",
  ml: "edward0rtiz/holbertonschool-machine_learning",
  sl: "allelomorph/holbertonschool-system_linux",
  sa: "allelomorph/holbertonschool-system_algorithms",
};

const man = (name, sec = 1) => [`man ${name}(${sec})`, `https://man7.org/linux/man-pages/man${sec}/${name}.${sec}.html`];
const mdn = (label, path) => [label + " (MDN)", "https://developer.mozilla.org/en-US/docs/" + path];
const py = (label, path) => [label + " (Python docs)", "https://docs.python.org/3/" + path];

const BETTY = ["Betty style guide & linter", "https://github.com/alx-tools/Betty/wiki"];
const CBOOK = ["The C Programming Language (K&R) – the classic C book", "https://en.wikipedia.org/wiki/The_C_Programming_Language"];
const BEEJ_C = ["Beej's Guide to C Programming (free)", "https://beej.us/guide/bgc/html/split/"];
const CS50 = ["CS50x lectures on C (free)", "https://cs50.harvard.edu/x/"];
const PYTUT = py("The Python Tutorial", "tutorial/index.html");
const LINUXCMD = ["The Linux Command Line (free book)", "https://linuxcommand.org/tlcl.php"];
const BASHGUIDE = ["Bash Guide for Beginners", "https://tldp.org/LDP/Bash-Beginners-Guide/html/"];

